create or replace function public.revoke_event_access_code(p_code_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare org_id uuid; begin select e.organization_id into org_id from public.event_access_codes c join public.events e on e.id=c.event_id where c.id=p_code_id; if org_id is null or not private.can_manage_org(org_id) then raise exception 'Organization access denied' using errcode='42501'; end if; update public.event_access_codes set expires_at=now() where id=p_code_id; end $$;
revoke all on function public.revoke_event_access_code(uuid) from public,anon; grant execute on function public.revoke_event_access_code(uuid) to authenticated;
